// Agoda — monotonic stack family: nearest smaller element, days until warmer, circular next greater.
public static class MonoStack {
    // For each i, the value of the nearest element to the LEFT that is strictly smaller than a[i], or -1.
    public static int[] NearestSmallerLeft(int[] a) {
        if (a == null) return Array.Empty<int>();
        var res = new int[a.Length];
        var st = new Stack<int>();                       // values, strictly increasing from bottom to top
        for (int i = 0; i < a.Length; i++) {
            while (st.Count > 0 && st.Peek() >= a[i]) st.Pop();
            res[i] = st.Count == 0 ? -1 : st.Peek();
            st.Push(a[i]);
        }
        return res;
    }

    // LeetCode 739: for each day, how many days until a strictly warmer temperature (0 if never).
    public static int[] DaysUntilWarmer(int[] t) {
        if (t == null) return Array.Empty<int>();
        var res = new int[t.Length];
        var st = new Stack<int>();                       // indices of days still waiting for a warmer one
        for (int i = 0; i < t.Length; i++) {
            while (st.Count > 0 && t[st.Peek()] < t[i]) { int j = st.Pop(); res[j] = i - j; }
            st.Push(i);
        }
        return res;
    }

    // LeetCode 503: next strictly greater element walking forward with wrap-around, or -1.
    public static int[] NextGreaterCircular(int[] a) {
        if (a == null) return Array.Empty<int>();
        int n = a.Length;
        var res = new int[n]; Array.Fill(res, -1);
        var st = new Stack<int>();
        for (int k = 0; k < 2 * n; k++) {
            int i = k % n;
            while (st.Count > 0 && a[st.Peek()] < a[i]) res[st.Pop()] = a[i];
            if (k < n) st.Push(i);
        }
        return res;
    }
}
